-- Esquema de ElectroHogar Ventas en PostgreSQL.
-- Generado por docs/diseno/datos.py desde los modelos de Django; no se edita a mano.
-- De las tablas auth_* de Django se listan el usuario, el rol (grupo) y la tabla que los une.

CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" integer NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "inventario_categoria" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre" varchar(60) NOT NULL UNIQUE);
CREATE TABLE "inventario_producto" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "codigo" varchar(20) NOT NULL UNIQUE, "nombre" varchar(120) NOT NULL, "marca" varchar(60) NOT NULL, "modelo" varchar(60) NOT NULL, "categoria_id" bigint NOT NULL, "precio_venta" numeric(10, 2) NOT NULL, "costo" numeric(10, 2) NOT NULL, "stock_actual" integer NOT NULL CHECK ("stock_actual" >= 0), "stock_minimo" integer NOT NULL CHECK ("stock_minimo" >= 0), "imagen" varchar(100) NOT NULL, "activo" boolean NOT NULL);
CREATE TABLE "inventario_movimientostock" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "producto_id" bigint NOT NULL, "tipo" varchar(10) NOT NULL, "cantidad" integer NOT NULL, "usuario_id" integer NOT NULL, "fecha" timestamp with time zone NOT NULL, "motivo" varchar(200) NOT NULL);
CREATE TABLE "ventas_venta" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "fecha" timestamp with time zone NOT NULL, "cajero_id" integer NOT NULL, "estado" varchar(10) NOT NULL, "total" numeric(12, 2) NOT NULL, "anulada_por_id" integer NULL, "motivo_anulacion" varchar(200) NOT NULL);
CREATE TABLE "ventas_detalleventa" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "venta_id" bigint NOT NULL, "producto_id" bigint NOT NULL, "cantidad" integer NOT NULL CHECK ("cantidad" >= 0), "precio_unitario" numeric(10, 2) NOT NULL);
